const parse = (slug: string, r: T): CountryReportRow => ({
  livingCostMonthlyUsd: { min: r[0], max: r[1] },
  bachelorDuration: r[2],
  masterDuration: r[3],
  tuitionRange: `${r[4]} (жилд)`,
  admissionGeneral: `Банкны баталгаа: ${r[5]}. Цагийн ажил: ${r[6]}. Төгсөлтийн дараах виз: ${r[7]}.`,
  scholarshipInfo: r[8],
  visaLinks: [{ title: 'Визийн албан ёсны холбоос (тайланд домэйнээр өгсөн, шалгаагүй)', url: `https://${r[9]}` }],
  ...EXTRA[slug],
});

export const COUNTRY_REPORT: Record<string, CountryReportRow> = Object.fromEntries(Object.entries(TABLE).map(([slug, r]) => [slug, parse(slug, r)]));
